Action.Str:
import bsh.This;

try {

String varName = "everyGesture";
if (tasker.getJavaVariable(varName) != null ) {
	This old = tasker.getJavaVariable(varName);
	old.removeAll();
	old.unregister(); 
	if (old.scheduledExecutor != void) old.scheduledExecutor.shutdownNow();
	if (old.executor != void) old.executor.shutdownNow();
}
} catch(e) {}

try {
tasker.setJavaVariable("everyGesture", null );
} catch(e) {}

importManager = "https://raw.githubusercontent.com/mqwec43as/EveryGesture/refs/heads/main/code/lib/UpdateManager.bsh";
source(new URL(importManager));

updateManager = UpdateManager();
String targetPath;

targetPath = updateManager.importDialog();
if (targetPath != null) tasker.setVariable("everygesture_path", targetPath);

// * Delay before triggering ScreenEvent
everyGesture.EventDelay = 100;

// * Use dark theme for UI
everyGesture.useDarkTheme = true;

// * Update uses pre-release or not
everyGesture.updatePreRelease = false;

// * Maximum displayed action characters in the handle templates activity
everyGesture.maxDisplayTextLength = 50;

// * Task maximum duration
everyGesture.taskMaximumDuration = 40000;
